--
-- Table structure for table `price_forecasts`
--

DROP TABLE IF EXISTS `price_forecasts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `price_forecasts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `komoditas_id` bigint(20) unsigned NOT NULL,
  `tanggal` date NOT NULL,
  `harga_aktual` decimal(15,2) DEFAULT NULL,
  `harga_prediksi` decimal(15,2) NOT NULL,
  `harga_lower` decimal(15,2) DEFAULT NULL,
  `harga_upper` decimal(15,2) DEFAULT NULL,
  `periode` enum('weekly','monthly','yearly') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'weekly',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `forecast_result_id` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `price_forecasts_komoditas_id_foreign` (`komoditas_id`),
  KEY `fk_price_forecasts_result` (`forecast_result_id`),
  CONSTRAINT `fk_price_forecasts_result` FOREIGN KEY (`forecast_result_id`) REFERENCES `forecast_results` (`id`) ON DELETE SET NULL,
  CONSTRAINT `price_forecasts_komoditas_id_foreign` FOREIGN KEY (`komoditas_id`) REFERENCES `master_komoditas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18971 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

